<?php require_once '../includes/auth.php'; $allowed=['admin','supplier','distributor','shop']; require_role($allowed); $page_title='Advanced Reports'; $uid=(int)$_SESSION['user_id']; include '../includes/header.php'; include '../includes/sidebar.php';
$totalStock=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COALESCE(SUM(quantity),0) c FROM stock ".($_SESSION['role']=='admin'?"":"WHERE owner_id=$uid")))['c'];
$totalSales=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COALESCE(SUM(grand_total),0) c FROM sales ".($_SESSION['role']=='shop'?"WHERE shop_id=$uid":"")))['c'];
$low=$_SESSION['role']=='admin'?mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(*) c FROM stock WHERE quantity<=reorder_level"))['c']:low_stock_count($conn,$uid);
?>
<div class="row g-4"><div class="col-md-4"><div class="card-box"><p>Total Stock</p><h2><?php echo $totalStock; ?></h2></div></div><div class="col-md-4"><div class="card-box"><p>Total Sales</p><h2>₹<?php echo money($totalSales); ?></h2></div></div><div class="col-md-4"><div class="card-box"><p>Low Stock Items</p><h2><?php echo $low; ?></h2></div></div></div><div class="card-box mt-4"><h5>Chart Analytics</h5><canvas id="reportChart" height="95"></canvas></div><script>new Chart(document.getElementById('reportChart'),{type:'line',data:{labels:['Stock','Sales','Low Stock'],datasets:[{label:'Analytics',data:[<?php echo $totalStock; ?>,<?php echo (float)$totalSales; ?>,<?php echo $low; ?>]}]}});</script><?php include '../includes/footer.php'; ?>
